import React, { useState } from 'react';
import { MOCK_ARTICLES, ICONS } from '../constants';
import { summarizeArticle } from '../services/gemini';

const Articles: React.FC = () => {
  const [summaries, setSummaries] = useState<Record<string, string>>({});
  const [loadingIds, setLoadingIds] = useState<Set<string>>(new Set());

  const handleSummarize = async (id: string, content: string) => {
    if (summaries[id]) return;

    setLoadingIds(prev => new Set(prev).add(id));
    const summary = await summarizeArticle(content);
    setSummaries(prev => ({ ...prev, [id]: summary || 'No summary available.' }));
    setLoadingIds(prev => {
      const next = new Set(prev);
      next.delete(id);
      return next;
    });
  };

  return (
    <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold tracking-tight">Writing & Thoughts</h1>
          <p className="text-slate-500 mt-1">Deep dives into technology, design, and engineering.</p>
        </div>
        <div className="flex items-center space-x-2 bg-white px-4 py-2 rounded-xl border border-slate-200 shadow-sm">
          <svg className="w-5 h-5 text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round"/></svg>
          <input type="text" placeholder="Search articles..." className="bg-transparent border-none outline-none text-sm w-48 md:w-64" />
        </div>
      </div>

      <div className="grid gap-8">
        {MOCK_ARTICLES.map((article) => (
          <article key={article.id} className="bg-white rounded-3xl border border-slate-200 overflow-hidden shadow-sm hover:shadow-md transition-all">
            <div className="grid md:grid-cols-5 gap-0">
              <div className="md:col-span-2 overflow-hidden">
                <img src={article.image} className="w-full h-full object-cover aspect-video md:aspect-auto" alt={article.title} />
              </div>
              <div className="md:col-span-3 p-6 md:p-8 flex flex-col justify-center">
                <div className="flex items-center space-x-3 text-xs font-bold text-indigo-600 uppercase tracking-widest mb-3">
                  <span>{article.category}</span>
                  <span className="w-1 h-1 bg-slate-300 rounded-full" />
                  <span className="text-slate-400">{article.date}</span>
                  <span className="w-1 h-1 bg-slate-300 rounded-full" />
                  <span className="text-slate-400">{article.readTime}</span>
                </div>
                <h2 className="text-2xl font-bold text-slate-900 mb-3 group-hover:text-indigo-600">{article.title}</h2>
                <p className="text-slate-600 leading-relaxed mb-6">{article.excerpt}</p>

                <div className="flex flex-wrap items-center gap-4 mt-auto">
                  <button className="flex items-center space-x-2 px-6 py-2.5 bg-slate-900 text-white rounded-xl font-bold hover:bg-slate-800 transition-colors">
                    <span>Read Full Story</span>
                    <ICONS.ChevronRight className="w-4 h-4" />
                  </button>
                  <button 
                    onClick={() => handleSummarize(article.id, article.excerpt)}
                    disabled={loadingIds.has(article.id)}
                    className="flex items-center space-x-2 px-4 py-2.5 bg-indigo-50 text-indigo-700 rounded-xl font-bold hover:bg-indigo-100 transition-colors disabled:opacity-50"
                  >
                    <ICONS.Sparkles className={`w-4 h-4 ${loadingIds.has(article.id) ? 'animate-spin' : ''}`} />
                    <span>{loadingIds.has(article.id) ? 'Summarizing...' : 'AI Summary'}</span>
                  </button>
                </div>

                {/* AI Summary View */}
                {summaries[article.id] && (
                  <div className="mt-6 p-5 bg-indigo-50/50 rounded-2xl border border-indigo-100 animate-in fade-in zoom-in-95 duration-300">
                    <div className="flex items-center space-x-2 mb-2 text-indigo-700">
                      <ICONS.Sparkles className="w-4 h-4" />
                      <span className="text-xs font-bold uppercase tracking-wider">Nova AI Summary</span>
                    </div>
                    <div className="text-sm text-slate-700 prose prose-indigo">
                      {summaries[article.id].split('\n').map((line, i) => (
                        <p key={i} className="mb-1">{line}</p>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </div>
          </article>
        ))}
      </div>
    </div>
  );
};

export default Articles;

