          <input type="text" placeholder="搜索文章..." className="bg-transparent border-none outline-none text-sm w-48 md:w-64" />
        </div>
      </div>

      <div className="grid gap-8">
        {MOCK_ARTICLES.map((article) => (
          <article key={article.id} className="bg-white rounded-3xl border border-slate-200 overflow-hidden shadow-sm hover:shadow-md transition-all">
