                  <span className="w-1 h-1 bg-slate-300 rounded-full" />
                  <span className="text-slate-400">{article.date}</span>
                  <span className="w-1 h-1 bg-slate-300 rounded-full" />
                  <span className="text-slate-400">{article.readTime}</span>
                </div>
                <h2 className="text-2xl font-bold text-slate-900 mb-3 group-hover:text-indigo-600">{article.title}</h2>
                <p className="text-slate-600 leading-relaxed mb-6">{article.excerpt}</p>

                <div className="flex flex-wrap items-center gap-4 mt-auto">
                  <button className="flex items-center space-x-2 px-6 py-2.5 bg-slate-900 text-white rounded-xl font-bold hover:bg-slate-800 transition-colors">
                    <span>阅读全文</span>
                    <ICONS.ChevronRight className="w-4 h-4" />
                  </button>
                  <button 
                    onClick={() => handleSummarize(article.id, article.excerpt)}
                    disabled={loadingIds.has(article.id)}
                    className="flex items-center space-x-2 px-4 py-2.5 bg-indigo-50 text-indigo-700 rounded-xl font-bold hover:bg-indigo-100 transition-colors disabled:opacity-50"
                  >
                    <ICONS.Sparkles className={`w-4 h-4 ${loadingIds.has(article.id) ? 'animate-spin' : ''}`} />
                    <span>{loadingIds.has(article.id) ? '正在生成摘要...' : 'AI 摘要'}</span>
                  </button>
                </div>

                {/* AI Summary View */}
                {summaries[article.id] && (
                  <div className="mt-6 p-5 bg-indigo-50/50 rounded-2xl border border-indigo-100 animate-in fade-in zoom-in-95 duration-300">
                    <div className="flex items-center space-x-2 mb-2 text-indigo-700">
                      <ICONS.Sparkles className="w-4 h-4" />
                      <span className="text-xs font-bold uppercase tracking-wider">Nova AI 摘要</span>
                    </div>
                    <div className="text-sm text-slate-700 prose prose-indigo">
                      {summaries[article.id].split('\n').map((line, i) => (
                        <p key={i} className="mb-1">{line}</p>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </div>
          </article>
        ))}
      </div>
    </div>
  );
};

