import React, { useState, useEffect } from 'react';
import { Page } from './types';
import { ICONS } from './constants';
import Sidebar from './components/Sidebar';
import Home from './pages/Home';
import Articles from './pages/Articles';
import Projects from './pages/Projects';
import Tools from './pages/Tools';
import Settings from './pages/Settings';
import Help from './pages/Help';

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState<Page>(Page.HOME);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);

  // Responsive sidebar handling
  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth < 768) {
        setIsSidebarOpen(false);
      } else {
        setIsSidebarOpen(true);
      }
    };
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const renderPage = () => {
    switch (currentPage) {
      case Page.HOME: return <Home onNavigate={setCurrentPage} />;
      case Page.ARTICLES: return <Articles />;
      case Page.PROJECTS: return <Projects />;
      case Page.TOOLS: return <Tools />;
      case Page.SETTINGS: return <Settings />;
      case Page.HELP: return <Help />;
      default: return <Home onNavigate={setCurrentPage} />;
    }
  };

  return (
    <div className="flex min-h-screen bg-slate-50 text-slate-900 transition-all duration-300">
      {/* Mobile Header */}
      <div className="md:hidden fixed top-0 left-0 right-0 h-16 bg-white border-b border-slate-200 z-50 flex items-center px-4 justify-between glass-effect">
        <div className="flex items-center space-x-2">
          <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white font-bold">N</div>
          <span className="font-bold text-xl tracking-tight">Nova</span>
        </div>
        <button 
          onClick={() => setIsSidebarOpen(!isSidebarOpen)}
          className="p-2 hover:bg-slate-100 rounded-lg transition-colors"
          aria-label="切换菜单"
        >
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16m-7 6h7" />
          </svg>
        </button>
      </div>

      <Sidebar 
        activePage={currentPage} 
        onPageChange={setCurrentPage} 
        isOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
      />

      <main className={`flex-1 transition-all duration-300 ${isSidebarOpen ? 'md:ml-64' : 'ml-0'} pt-16 md:pt-0`}>
        <div className="max-w-6xl mx-auto p-4 md:p-8">
          <div className="animate-in fade-in duration-500">
            {renderPage()}
          </div>
        </div>
      </main>

      {/* Floating AI Bubble */}
      <div className="fixed bottom-6 right-6 z-50">
        <button 
          className="w-14 h-14 bg-indigo-600 text-white rounded-full shadow-lg flex items-center justify-center hover:scale-110 transition-all active:scale-95 group"
          title="咨询 Nova 助手"
        >
          <ICONS.Sparkles className="w-6 h-6 group-hover:rotate-12 transition-transform" />
        </button>
      </div>
    </div>
  );
};

