const Help: React.FC = () => {
  const [comments, setComments] = useState([
    { id: 1, name: '张工', content: '作品集做得非常漂亮！支持一下。', date: '2024-10-25' },
    { id: 2, name: '路人甲', content: '请问有联系方式吗？想咨询一个项目。', date: '2024-10-24' }
  ]);
  const [newName, setNewName] = useState('');
  const [newComment, setNewComment] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newName || !newComment) return;
    const comment = {
      id: Date.now(),
      name: newName,
      content: newComment,
      date: new Date().toISOString().split('T')[0]
    };
    setComments([comment, ...comments]);
    setNewName('');
    setNewComment('');
  };

  return (
    <div className="max-w-4xl mx-auto space-y-12 animate-in slide-in-from-bottom-4 duration-500 pb-20">
      <div className="text-center space-y-4">
        <h1 className="text-4xl font-bold tracking-tight">帮助与评论</h1>
        <p className="text-slate-500 max-w-lg mx-auto">有任何问题或者想对我说的，请在下方留言。</p>
      </div>

      <div className="grid md:grid-cols-3 gap-8">
        <section className="md:col-span-1 space-y-6">
          <h2 className="text-xl font-bold">常见问题</h2>
          <div className="space-y-4">
            <div className="bg-white p-4 rounded-2xl border border-slate-200">
              <p className="font-bold text-sm mb-1">如何定制相似的作品集？</p>
              <p className="text-xs text-slate-500">你可以通过底部的留言联系我进行外包咨询。</p>
            </div>
            <div className="bg-white p-4 rounded-2xl border border-slate-200">
              <p className="font-bold text-sm mb-1">使用的技术栈有哪些？</p>
              <p className="text-xs text-slate-500">React + Tailwind + Gemini AI API。</p>
            </div>
          </div>
        </section>

        <section className="md:col-span-2 space-y-6">
          <h2 className="text-xl font-bold">访客留言区</h2>
          <div className="bg-white rounded-3xl border border-slate-200 p-6 shadow-sm">
            <form onSubmit={handleSubmit} className="space-y-4 mb-8">
              <div className="grid grid-cols-2 gap-4">
                <input 
                  type="text" 
                  placeholder="您的昵称" 
                  value={newName}
                  onChange={(e) => setNewName(e.target.value)}
                  className="p-3 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm"
                />
              </div>
              <textarea 
                placeholder="留下您的评论..." 
                value={newComment}
                onChange={(e) => setNewComment(e.target.value)}
                className="w-full p-4 h-24 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm resize-none"
              />
              <button type="submit" className="px-6 py-2 bg-indigo-600 text-white rounded-xl font-bold text-sm hover:bg-indigo-700 transition-all">
                提交留言
              </button>
            </form>

            <div className="space-y-4">
              {comments.map(c => (
                <div key={c.id} className="p-4 bg-slate-50 rounded-2xl border border-slate-100 animate-in fade-in duration-300">
                  <div className="flex justify-between items-center mb-2">
                    <span className="font-bold text-sm">{c.name}</span>
                    <span className="text-[10px] text-slate-400">{c.date}</span>
