import React, { useState, useEffect } from 'react';
import { Page } from './types';
import { ICONS } from './constants';
import Sidebar from './components/Sidebar';
import Home from './pages/Home';
import Projects from './pages/Projects';
import Tools from './pages/Tools';
import Settings from './pages/Settings';
import Help from './pages/Help';

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState<Page>(Page.HOME);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);

  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth < 768) {
        setIsSidebarOpen(false);
      } else {
        setIsSidebarOpen(true);
      }
    };
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const renderPage = () => {
    switch (currentPage) {
      case Page.HOME: return <Home onNavigate={setCurrentPage} />;
      case Page.PROJECTS: return <Projects />;
      case Page.TOOLS: return <Tools />;
      case Page.SETTINGS: return <Settings />;
      case Page.HELP: return <Help />;
      default: return <Home onNavigate={setCurrentPage} />;
    }
  };

  return (
    <div className="flex min-h-screen bg-slate-50 text-slate-900 transition-all duration-300">
      {/* Mobile Header */}
      <div className="md:hidden fixed top-0 left-0 right-0 h-16 bg-white border-b border-slate-200 z-50 flex items-center px-4 justify-between glass-effect">
        <div className="flex items-center space-x-2">
          <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white font-bold">N</div>
          <span className="font-bold text-xl tracking-tight">Nova</span>
        </div>
        <button 
          onClick={() => setIsSidebarOpen(!isSidebarOpen)}
          className="p-2 hover:bg-slate-100 rounded-lg transition-colors"
          aria-label="切换菜单"
        >
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16m-7 6h7" />
          </svg>
        </button>
      </div>

      <Sidebar 
        activePage={currentPage} 
        onPageChange={setCurrentPage} 
        isOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
      />

      <main className={`flex-1 transition-all duration-300 ${isSidebarOpen ? 'md:ml-64' : 'ml-0'} pt-16 md:pt-0`}>
        <div className="max-w-6xl mx-auto p-4 md:p-8">
          <div className="animate-in fade-in duration-500">
            {renderPage()}
          </div>
        </div>
      </main>

      {/* Floating AI Bubble */}
      <div className="fixed bottom-6 right-6 z-50">
        <button 
          className="w-14 h-14 bg-indigo-600 text-white rounded-full shadow-lg flex items-center justify-center hover:scale-110 transition-all active:scale-95 group"
          title="咨询 Nova 助手"
        >
          <ICONS.Sparkles className="w-6 h-6 group-hover:rotate-12 transition-transform" />
        </button>
      </div>
    </div>
  );
};

export default App;

import React from 'react';
import { Page } from '../types';
import { ICONS } from '../constants';

interface SidebarProps {
  activePage: Page;
  onPageChange: (page: Page) => void;
  isOpen: boolean;
  onClose: () => void;
}

const Sidebar: React.FC<SidebarProps> = ({ activePage, onPageChange, isOpen, onClose }) => {
  const menuItems = [
    { id: Page.HOME, label: '主页', icon: ICONS.Home },
    { id: Page.PROJECTS, label: '项目作品', icon: ICONS.Project },
    { id: Page.TOOLS, label: '实用工具', icon: ICONS.Tools },
    { id: Page.HELP, label: '帮助与评论', icon: ICONS.Help },
    { id: Page.SETTINGS, label: '个人设置', icon: ICONS.Settings },
  ];

  return (
    <>
      {isOpen && (
        <div 
          className="md:hidden fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-40"
          onClick={onClose}
        />
      )}

      <aside className={`
        fixed top-0 left-0 h-full w-64 bg-white border-r border-slate-200 z-50
        transition-transform duration-300 ease-in-out
        ${isOpen ? 'translate-x-0' : '-translate-x-full md:translate-x-0'}
      `}>
        <div className="flex flex-col h-full">
          <div className="p-6 flex items-center justify-between">
            <div className="flex items-center space-x-3">
              <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center text-white shadow-lg">
                <span className="font-bold text-lg">N</span>
              </div>
              <div>
                <span className="font-bold text-lg leading-tight block">Nova</span>
                <span className="text-xs text-slate-500 font-medium">作品集项目</span>
              </div>
            </div>
            <button onClick={onClose} className="md:hidden p-1 text-slate-400">
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M6 18L18 6M6 6l12 12" strokeWidth={2}/></svg>
            </button>
          </div>

          <nav className="flex-1 px-4 py-2 space-y-1 overflow-y-auto">
            <p className="px-4 text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-2">菜单</p>
            {menuItems.map((item) => {
              const isActive = activePage === item.id;
              const Icon = item.icon as any;
              return (
                <button
                  key={item.id}
                  onClick={() => {
                    onPageChange(item.id);
                    if (window.innerWidth < 768) onClose();
                  }}
                  className={`
                    w-full flex items-center space-x-3 px-4 py-3 rounded-xl transition-all duration-200
                    ${isActive 
                      ? 'bg-indigo-50 text-indigo-700' 
                      : 'text-slate-600 hover:bg-slate-50 hover:text-slate-900'}
                  `}
                >
                  <Icon className={`w-5 h-5 ${isActive ? 'text-indigo-600' : 'text-slate-400'}`} />
                  <span className="font-medium">{item.label}</span>
                </button>
              );
            })}
          </nav>

          <div className="p-4 border-t border-slate-100 bg-slate-50/50">
            <div className="flex items-center space-x-3 p-2">
              <img src="https://picsum.photos/seed/u1/100/100" className="w-8 h-8 rounded-full border border-white" alt="" />
              <div className="flex-1 min-w-0">
                <p className="text-sm font-semibold text-slate-900 truncate">管理员</p>
              </div>
            </div>
          </div>
        </div>
      </aside>
    </>
  );
};

export default Sidebar;

