import React, { useState, useEffect } from 'react';
import { MOCK_PROJECTS, ICONS } from '../constants';
import { marked } from 'marked';
import { Comment } from '../types';

interface ProjectsProps {
  isAdmin: boolean;
}

const Projects: React.FC<ProjectsProps> = ({ isAdmin }) => {
  const [selectedProjectId, setSelectedProjectId] = useState<string | null>(null);
  const [articleContent, setArticleContent] = useState<string>('');
  const [isLoading, setIsLoading] = useState(false);

  // Comments logic
  const [comments, setComments] = useState<Comment[]>([]);
  const [commentName, setCommentName] = useState('');
  const [commentText, setCommentText] = useState('');

  const activeProject = MOCK_PROJECTS.find(p => p.id === selectedProjectId);

  useEffect(() => {
    // Load comments from local storage
    const saved = localStorage.getItem('nova_comments');
    if (saved) {
      setComments(JSON.parse(saved));
    }
  }, []);

  const saveComments = (newComments: Comment[]) => {
    setComments(newComments);
    localStorage.setItem('nova_comments', JSON.stringify(newComments));
  };

  useEffect(() => {
    if (selectedProjectId && activeProject?.articleId) {
      loadArticle(activeProject.articleId);
    }
  }, [selectedProjectId]);

  const loadArticle = async (id: string) => {
    setIsLoading(true);
    try {
      const response = await fetch(`./articles/${id}.md`);
      const text = await response.text();
      setArticleContent(marked.parse(text) as string);
    } catch (error) {
      setArticleContent('<p className="text-red-500">无法加载文档内容。</p>');
    } finally {
      setIsLoading(false);
    }
  };

  const handleAddComment = (e: React.FormEvent) => {
    e.preventDefault();
    if (!commentName || !commentText || !selectedProjectId) return;

    const newComment: Comment = {
      id: Date.now().toString(),
      projectId: selectedProjectId,
      author: commentName,
      content: commentText,
      date: new Date().toLocaleDateString('zh-CN')
    };

    saveComments([newComment, ...comments]);
    setCommentName('');
    setCommentText('');
  };

  const handleDeleteComment = (id: string) => {
    if (window.confirm('确定要删除这条评论吗？')) {
      saveComments(comments.filter(c => c.id !== id));
    }
  };

  if (selectedProjectId && activeProject) {
    const projectComments = comments.filter(c => c.projectId === selectedProjectId);

    return (
      <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 space-y-8 pb-20">
        <button 
          onClick={() => setSelectedProjectId(null)}
          className="flex items-center space-x-2 text-indigo-600 hover:text-indigo-700 font-bold transition-colors"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M15 19l-7-7 7-7" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round"/></svg>
          <span>返回项目列表</span>
        </button>

        <div className="bg-white rounded-[40px] border border-slate-200 overflow-hidden shadow-sm">
          <div className="h-64 overflow-hidden relative">
            <img src={activeProject.image} className="w-full h-full object-cover" alt="" />
            <div className="absolute inset-0 bg-gradient-to-t from-white via-white/20 to-transparent" />
          </div>

          <div className="p-8 md:p-12 -mt-20 relative">
            <div className="flex flex-wrap gap-2 mb-4">
              {activeProject.tech.map(t => (
                <span key={t} className="px-3 py-1 bg-indigo-100 text-indigo-700 text-[10px] font-bold uppercase tracking-widest rounded-full">{t}</span>
              ))}
            </div>
            <h1 className="text-4xl font-extrabold mb-8">{activeProject.name}</h1>

            {isLoading ? (
              <div className="flex justify-center py-20">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600"></div>
              </div>
            ) : (
              <div 
                className="prose max-w-none mb-16"
                dangerouslySetInnerHTML={{ __html: articleContent }}
              />
            )}

            <div className="border-t border-slate-100 pt-12">
              <h2 className="text-2xl font-bold mb-8">访客互动 ({projectComments.length})</h2>

              <form onSubmit={handleAddComment} className="bg-slate-50 p-6 rounded-3xl space-y-4 mb-10">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <input 
                    type="text" 
                    placeholder="您的昵称" 
                    value={commentName}
                    onChange={(e) => setCommentName(e.target.value)}
                    className="p-3 bg-white border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm"
                  />
                </div>
                <textarea 
                  placeholder="说点什么吧..." 
                  value={commentText}
                  onChange={(e) => setCommentText(e.target.value)}
                  className="w-full p-4 h-32 bg-white border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm resize-none"
                />
                <button type="submit" className="px-8 py-3 bg-indigo-600 text-white rounded-xl font-bold hover:bg-indigo-700 transition-all shadow-md">
                  提交评论
                </button>
              </form>

              <div className="space-y-6">
                {projectComments.length > 0 ? projectComments.map(c => (
                  <div key={c.id} className="group p-6 bg-white border border-slate-100 rounded-3xl shadow-sm hover:shadow-md transition-all relative">
                    <div className="flex justify-between items-start mb-2">
                      <div className="flex items-center space-x-3">
                        <div className="w-8 h-8 rounded-full bg-slate-200 flex items-center justify-center text-xs font-bold text-slate-500">
                          {c.author[0]?.toUpperCase()}
                        </div>
                        <span className="font-bold text-slate-900">{c.author}</span>
                      </div>
                      <div className="flex items-center space-x-4">
                        <span className="text-[10px] text-slate-400 font-medium">{c.date}</span>
                        {isAdmin && (
                          <button 
                            onClick={() => handleDeleteComment(c.id)}
                            className="p-2 text-red-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-all opacity-0 group-hover:opacity-100"
                            title="删除评论"
                          >
                            <ICONS.Trash className="w-4 h-4" />
                          </button>
                        )}
                      </div>
                    </div>
                    <p className="text-sm text-slate-600 leading-relaxed pl-11">{c.content}</p>
                  </div>
                )) : (
                  <div className="text-center py-10 bg-slate-50 rounded-3xl border border-dashed border-slate-200">
                    <p className="text-slate-400 text-sm">暂无评论，快来抢沙发吧！</p>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500">
      <div className="max-w-3xl">
        <h1 className="text-3xl font-bold tracking-tight">项目作品</h1>
        <p className="text-slate-500 mt-2 text-lg">近期作品选集，涵盖从企业级平台到实验性的 UI/UX 研究。点击卡片阅读详细文档。</p>
      </div>

      <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-8">
        {MOCK_PROJECTS.map((project) => (
          <div 
            key={project.id} 
            onClick={() => setSelectedProjectId(project.id)}
            className="group bg-white rounded-[32px] border border-slate-200 overflow-hidden shadow-sm hover:shadow-2xl transition-all duration-500 flex flex-col cursor-pointer hover:-translate-y-1"
          >
            <div className="relative overflow-hidden h-52">
              <img src={project.image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" alt={project.name} />
              <div className="absolute inset-0 bg-indigo-900/10 group-hover:bg-indigo-900/0 transition-colors" />
              <div className="absolute top-4 right-4 bg-white/90 backdrop-blur px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest text-indigo-600 shadow-sm">
                查看文章
              </div>
            </div>
            <div className="p-7 flex-1 flex flex-col">
              <div className="flex flex-wrap gap-1.5 mb-3">
                {project.tech.map((t: string) => (
                  <span key={t} className="px-2 py-0.5 bg-slate-50 text-slate-500 text-[9px] font-bold uppercase tracking-wider rounded border border-slate-100">{t}</span>
                ))}
              </div>
              <h3 className="text-xl font-bold mb-2 group-hover:text-indigo-600 transition-colors">{project.name}</h3>
              <p className="text-slate-500 text-sm mb-4 flex-1 leading-relaxed line-clamp-2">{project.description}</p>
              <div className="flex items-center justify-between pt-4 border-t border-slate-50 mt-auto">
                <span className="text-indigo-600 font-bold text-xs flex items-center space-x-1 group-hover:translate-x-1 transition-transform">
                  <span>深度解析文章</span>
                  <ICONS.ChevronRight className="w-3 h-3" />
                </span>
                <ICONS.Github className="w-4 h-4 text-slate-300 group-hover:text-slate-600 transition-colors" />
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Projects;

