import React, { useState, useEffect } from 'react';
import { Project, Comment } from '../types';
import { ICONS } from '../constants';
import { marked } from 'marked';

interface ProjectsProps {
  isAdmin: boolean;
  projects: Project[];
  comments: Comment[];
  onUpdateComments: (comments: Comment[]) => void;
}

const Projects: React.FC<ProjectsProps> = ({ isAdmin, projects, comments, onUpdateComments }) => {
  const [selectedProjectId, setSelectedProjectId] = useState<string | null>(null);
  const [articleContent, setArticleContent] = useState<string>('');
  const [isLoading, setIsLoading] = useState(false);
  const [commentName, setCommentName] = useState('');
  const [commentText, setCommentText] = useState('');

  const activeProject = projects.find(p => p.id === selectedProjectId);

  useEffect(() => {
    if (selectedProjectId && activeProject?.articleId) {
      loadArticle(activeProject.articleId);
    }
  }, [selectedProjectId]);

  const loadArticle = async (id: string) => {
    setIsLoading(true);
    try {
      const response = await fetch(`./articles/${id}.md`);
      const text = await response.text();
      setArticleContent(marked.parse(text) as string);
    } catch (error) {
      setArticleContent('<p class="text-red-500">无法加载文档内容。</p>');
    } finally {
      setIsLoading(false);
    }
  };

  const handleAddComment = (e: React.FormEvent) => {
    e.preventDefault();
    if (!commentName || !commentText || !selectedProjectId || !activeProject) return;

    const newComment: Comment = {
      id: Date.now().toString(),
      projectId: selectedProjectId,
      projectDisplayName: activeProject.name,
      author: commentName,
      content: commentText,
      date: new Date().toLocaleDateString('zh-CN', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' })
    };

    onUpdateComments([newComment, ...comments]);
    setCommentName('');
    setCommentText('');
  };

  const handleDeleteComment = (id: string) => {
    if (window.confirm('确定要删除这条评论吗？')) {
      onUpdateComments(comments.filter(c => c.id !== id));
    }
  };

  if (selectedProjectId && activeProject) {
    const projectComments = comments.filter(c => c.projectId === selectedProjectId);

    return (
      <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 space-y-8 pb-20">
        <button 
          onClick={() => setSelectedProjectId(null)}
