import React, { useState, useEffect } from 'react';
import { Project, Comment } from '../types';
import { ICONS } from '../constants';
import { marked } from 'marked';

interface ProjectsProps {
  isAdmin: boolean;
  projects: Project[];
  comments: Comment[];
  onUpdateComments: (comments: Comment[]) => void;
}

const Projects: React.FC<ProjectsProps> = ({ isAdmin, projects, comments, onUpdateComments }) => {
  const [selectedProjectId, setSelectedProjectId] = useState<string | null>(null);
  const [articleContent, setArticleContent] = useState<string>('');
  const [isLoading, setIsLoading] = useState(false);
  const [commentName, setCommentName] = useState('');
  const [commentText, setCommentText] = useState('');
  const [replyToId, setReplyToId] = useState<string | null>(null);
  const [replyText, setReplyText] = useState('');

  const activeProject = projects.find(p => p.id === selectedProjectId);

  useEffect(() => {
    if (selectedProjectId && activeProject?.articleId) {
      loadArticle(activeProject.articleId);
    }
  }, [selectedProjectId]);

  const loadArticle = async (id: string) => {
    setIsLoading(true);
    try {
      const response = await fetch(`./articles/${id}.md`);
      const text = await response.text();
      setArticleContent(marked.parse(text) as string);
    } catch (error) {
      setArticleContent('<p class="text-red-500">无法加载文档内容。</p>');
    } finally {
      setIsLoading(false);
    }
  };

  const handleAddComment = (e: React.FormEvent, parentId?: string) => {
    e.preventDefault();
    const name = parentId ? "匿名访客" : commentName; // 回复默认匿名或可扩展
    const text = parentId ? replyText : commentText;

    if (!text || !selectedProjectId || !activeProject) return;
    if (!parentId && !commentName) return;

    const newComment: Comment = {
      id: Date.now().toString(),
      projectId: selectedProjectId,
      projectDisplayName: activeProject.name,
      author: name,
      content: text,
      date: new Date().toLocaleDateString('zh-CN', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }),
      parentId: parentId
    };

    onUpdateComments([newComment, ...comments]);

    if (parentId) {
      setReplyToId(null);
      setReplyText('');
    } else {
      setCommentName('');
      setCommentText('');
    }
  };

  const handleDeleteComment = (id: string) => {
    if (window.confirm('确定要删除这条评论及其所有回复吗？')) {
      // 级联删除：删除该 ID 及其所有以该 ID 为 parentId 的回复
      onUpdateComments(comments.filter(c => c.id !== id && c.parentId !== id));
    }
  };

  // 渲染评论及其回复
  const renderCommentThread = (comment: Comment, allComments: Comment[]) => {
    const replies = allComments.filter(c => c.parentId === comment.id);

    return (
      <div key={comment.id} className="space-y-4">
        <div className="group p-6 bg-white border border-slate-100 rounded-3xl shadow-sm hover:shadow-md transition-all relative">
          <div className="flex justify-between items-start mb-2">
            <div className="flex items-center space-x-3">
              <div className="w-8 h-8 rounded-full bg-indigo-100 flex items-center justify-center text-xs font-bold text-indigo-600">
                {comment.author[0]?.toUpperCase()}
              </div>
              <span className="font-bold text-slate-900">{comment.author}</span>
            </div>
            <div className="flex items-center space-x-4">
              <span className="text-[10px] text-slate-400 font-medium">{comment.date}</span>
              <button 
                onClick={() => setReplyToId(replyToId === comment.id ? null : comment.id)}
                className="text-xs font-bold text-indigo-600 hover:underline"
              >
                回复
              </button>
              {isAdmin && (
                <button 
                  onClick={() => handleDeleteComment(comment.id)}
                  className="p-2 text-red-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-all opacity-0 group-hover:opacity-100"
                >
                  <ICONS.Trash className="w-4 h-4" />
                </button>
              )}
            </div>
          </div>
          <p className="text-sm text-slate-600 leading-relaxed pl-11">{comment.content}</p>

          {/* 回复输入框 */}
          {replyToId === comment.id && (
            <div className="mt-4 pl-11 animate-in slide-in-from-top-2">
              <div className="flex gap-2">
                <input 
                  autoFocus
                  className="flex-1 p-2 bg-slate-50 border border-slate-200 rounded-xl text-xs outline-none focus:ring-1 focus:ring-indigo-500"
                  placeholder={`回复 ${comment.author}...`}
                  value={replyText}
                  onChange={e => setReplyText(e.target.value)}
                />
                <button 
                  onClick={(e) => handleAddComment(e, comment.id)}
                  className="px-4 py-2 bg-indigo-600 text-white rounded-xl text-xs font-bold"
                >
                  发送
                </button>
              </div>
            </div>
          )}
        </div>

        {/* 渲染子回复 */}
        {replies.length > 0 && (
          <div className="ml-12 border-l-2 border-slate-100 pl-6 space-y-4">
            {replies.map(reply => (
              <div key={reply.id} className="group p-4 bg-slate-50/50 border border-slate-100 rounded-2xl relative">
                <div className="flex justify-between items-start mb-1">
                  <div className="flex items-center space-x-2">
                    <span className="font-bold text-xs text-slate-900">{reply.author}</span>
                    <span className="text-[10px] text-slate-400 font-medium">{reply.date}</span>
                  </div>
                  {isAdmin && (
                    <button 
                      onClick={() => handleDeleteComment(reply.id)}
                      className="text-red-400 opacity-0 group-hover:opacity-100 transition-all"
                    >
                      <ICONS.Trash className="w-3 h-3" />
                    </button>
                  )}
                </div>
                <p className="text-xs text-slate-600 leading-relaxed">{reply.content}</p>
              </div>
            ))}
          </div>
        )}
      </div>
    );
  };

  if (selectedProjectId && activeProject) {
    const projectComments = comments.filter(c => c.projectId === selectedProjectId);
    const rootComments = projectComments.filter(c => !c.parentId);

    return (
      <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 space-y-8 pb-20">
        <button 
          onClick={() => setSelectedProjectId(null)}
          className="flex items-center space-x-2 text-indigo-600 hover:text-indigo-700 font-bold transition-colors"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M15 19l-7-7 7-7" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round"/></svg>
          <span>返回项目列表</span>
        </button>

        <div className="bg-white rounded-[40px] border border-slate-200 overflow-hidden shadow-sm">
          <div className="h-64 overflow-hidden relative">
            <img src={activeProject.image} className="w-full h-full object-cover" alt="" />
            <div className="absolute inset-0 bg-gradient-to-t from-white via-white/20 to-transparent" />
          </div>

          <div className="p-8 md:p-12 -mt-20 relative">
            <div className="flex flex-wrap gap-2 mb-4">
              {activeProject.tech.map(t => (
                <span key={t} className="px-3 py-1 bg-indigo-100 text-indigo-700 text-[10px] font-bold uppercase tracking-widest rounded-full">{t}</span>
              ))}
            </div>
            <h1 className="text-4xl font-extrabold mb-8">{activeProject.name}</h1>

            {isLoading ? (
              <div className="flex justify-center py-20">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600"></div>
              </div>
            ) : (
              <div 
                className="prose max-w-none mb-16"
                dangerouslySetInnerHTML={{ __html: articleContent }}
              />
            )}

            <div className="border-t border-slate-100 pt-12">
              <h2 className="text-2xl font-bold mb-8">访客互动 ({projectComments.length})</h2>

              <form onSubmit={handleAddComment} className="bg-slate-50 p-6 rounded-3xl space-y-4 mb-10">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <input 
                    type="text" 
                    placeholder="您的昵称" 
                    value={commentName}
                    onChange={(e) => setCommentName(e.target.value)}
                    className="p-3 bg-white border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm"
                  />
                </div>
                <textarea 
                  placeholder="说点什么吧..." 
                  value={commentText}
                  onChange={(e) => setCommentText(e.target.value)}
                  className="w-full p-4 h-32 bg-white border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm resize-none"
                />
                <button type="submit" className="px-8 py-3 bg-indigo-600 text-white rounded-xl font-bold hover:bg-indigo-700 transition-all shadow-md">
                  发表评论
                </button>
              </form>

              <div className="space-y-8">
                {rootComments.length > 0 ? rootComments.map(c => renderCommentThread(c, projectComments)) : (
                  <div className="text-center py-10 bg-slate-50 rounded-3xl border border-dashed border-slate-200">
                    <p className="text-slate-400 text-sm">暂无评论，快来抢沙发吧！</p>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500">
      <div className="max-w-3xl">
        <h1 className="text-3xl font-bold tracking-tight">项目作品</h1>
        <p className="text-slate-500 mt-2 text-lg">近期作品选集，涵盖从企业级平台到实验性的 UI/UX 研究。</p>
      </div>

      <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-8">
        {projects.map((project) => (
          <div 
            key={project.id} 
            onClick={() => setSelectedProjectId(project.id)}
            className="group bg-white rounded-[32px] border border-slate-200 overflow-hidden shadow-sm hover:shadow-2xl transition-all duration-500 flex flex-col cursor-pointer hover:-translate-y-1"
          >
            <div className="relative overflow-hidden h-52">
              <img src={project.image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" alt={project.name} />
              <div className="absolute top-4 right-4 flex gap-2">
                {project.isFeatured && <span className="bg-indigo-600 text-white px-2 py-0.5 rounded text-[8px] font-bold uppercase">精选</span>}
                {project.isLatest && <span className="bg-green-600 text-white px-2 py-0.5 rounded text-[8px] font-bold uppercase">最新</span>}
              </div>
            </div>
            <div className="p-7 flex-1 flex flex-col">
              <h3 className="text-xl font-bold mb-2 group-hover:text-indigo-600 transition-colors">{project.name}</h3>
              <p className="text-slate-500 text-sm mb-4 line-clamp-2">{project.description}</p>
              <div className="flex items-center justify-between pt-4 border-t border-slate-50 mt-auto">
                <span className="text-indigo-600 font-bold text-xs">深度解析文档</span>
                <ICONS.ChevronRight className="w-3 h-3 text-indigo-600" />
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Projects;

import React from 'react';
import { Project, Comment } from '../types';
import { ICONS } from '../constants';

interface AdminDashboardProps {
  projects: Project[];
  setProjects: (projects: Project[]) => void;
  comments: Comment[];
  setComments: (comments: Comment[]) => void;
  onLogout: () => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ projects, setProjects, comments, setComments, onLogout }) => {
  const toggleFeatured = (id: string) => {
    setProjects(projects.map(p => p.id === id ? { ...p, isFeatured: !p.isFeatured } : p));
  };

  const toggleLatest = (id: string) => {
    setProjects(projects.map(p => p.id === id ? { ...p, isLatest: !p.isLatest } : p));
  };

  const deleteComment = (id: string) => {
    if (confirm('确认删除该评论及其回复？')) {
      setComments(comments.filter(c => c.id !== id && c.parentId !== id));
    }
  };

  return (
    <div className="space-y-10 animate-in fade-in duration-500 pb-20">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">管理员控制台</h1>
          <p className="text-slate-500">管理您的内容资产、评论及站点配置。</p>
        </div>
        <button onClick={onLogout} className="px-6 py-2 border border-red-200 text-red-600 rounded-xl font-bold hover:bg-red-50 transition-all text-sm">
          退出登录
        </button>
      </div>

      {/* Projects Management */}
      <section className="bg-white rounded-[32px] border border-slate-200 overflow-hidden shadow-sm">
        <div className="p-6 border-b border-slate-100 bg-slate-50/50">
          <h2 className="font-bold text-lg">作品与文章管理</h2>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="text-slate-400 text-[10px] font-bold uppercase tracking-widest border-b border-slate-50">
                <th className="px-6 py-4">作品名称</th>
                <th className="px-6 py-4">精选状态</th>
                <th className="px-6 py-4">最新标志</th>
                <th className="px-6 py-4">关联文档</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {projects.map(p => (
                <tr key={p.id} className="hover:bg-slate-50 transition-colors">
                  <td className="px-6 py-4">
                    <div className="flex items-center space-x-3">
                      <img src={p.image} className="w-10 h-10 rounded-lg object-cover" alt="" />
                      <span className="font-bold text-sm">{p.name}</span>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <button 
                      onClick={() => toggleFeatured(p.id)}
                      className={`px-3 py-1 rounded-full text-[10px] font-bold transition-all ${p.isFeatured ? 'bg-indigo-100 text-indigo-700' : 'bg-slate-100 text-slate-400'}`}
                    >
                      {p.isFeatured ? '已精选' : '非精选'}
                    </button>
                  </td>
                  <td className="px-6 py-4">
                    <button 
                      onClick={() => toggleLatest(p.id)}
                      className={`px-3 py-1 rounded-full text-[10px] font-bold transition-all ${p.isLatest ? 'bg-green-100 text-green-700' : 'bg-slate-100 text-slate-400'}`}
                    >
                      {p.isLatest ? '已设最新' : '普通文章'}
                    </button>
                  </td>
                  <td className="px-6 py-4 text-xs text-slate-400 font-mono">
                    {p.articleId}.md
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </section>

      {/* Comments Management */}
      <section className="bg-white rounded-[32px] border border-slate-200 overflow-hidden shadow-sm">
        <div className="p-6 border-b border-slate-100 bg-slate-50/50">
          <h2 className="font-bold text-lg">全站评论管理</h2>
        </div>
        <div className="divide-y divide-slate-50">
          {comments.length > 0 ? comments.map(c => (
            <div key={c.id} className={`p-6 flex items-start justify-between group ${c.parentId ? 'bg-slate-50/30 ml-8 border-l-2 border-indigo-50' : ''}`}>
              <div className="space-y-1">
                <div className="flex items-center space-x-2">
                  <span className="font-bold text-sm">{c.author}</span>
                  {c.parentId && <span className="text-[10px] bg-indigo-50 text-indigo-600 px-1.5 rounded">回复</span>}
                  <span className="text-[10px] text-slate-400">在</span>
                  <span className="text-[10px] font-bold text-indigo-600">《{c.projectDisplayName}》</span>
                  <span className="text-[10px] text-slate-400">于 {c.date}</span>
                </div>
                <p className="text-sm text-slate-600">{c.content}</p>
              </div>
              <button 
                onClick={() => deleteComment(c.id)}
                className="p-2 text-red-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-all opacity-0 group-hover:opacity-100"
