import React, { useState, useEffect } from 'react';
import { Project, Comment } from '../types';
import { ICONS } from '../constants';
import { marked } from 'marked';

interface ProjectsProps {
  isAdmin: boolean;
  projects: Project[];
  comments: Comment[];
  onUpdateComments: (comments: Comment[]) => void;
}

const Projects: React.FC<ProjectsProps> = ({ isAdmin, projects, comments, onUpdateComments }) => {
  const [selectedProjectId, setSelectedProjectId] = useState<string | null>(null);
  const [articleContent, setArticleContent] = useState<string>('');
  const [isLoading, setIsLoading] = useState(false);
  const [commentName, setCommentName] = useState('');
  const [commentText, setCommentText] = useState('');
  const [replyToId, setReplyToId] = useState<string | null>(null);
  const [replyText, setReplyText] = useState('');
  const [searchQuery, setSearchQuery] = useState('');

  const activeProject = projects.find(p => p.id === selectedProjectId);

  const filteredProjects = projects.filter(p => 
    p.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
    p.description.toLowerCase().includes(searchQuery.toLowerCase()) ||
    p.tech.some(t => t.toLowerCase().includes(searchQuery.toLowerCase()))
  );

  useEffect(() => {
    if (selectedProjectId && activeProject?.articleId) {
      loadArticle(activeProject.articleId);
    }
  }, [selectedProjectId]);

  const loadArticle = async (id: string) => {
    setIsLoading(true);
    try {
      const response = await fetch(`./articles/${id}.md`);
      const text = await response.text();
      setArticleContent(marked.parse(text) as string);
    } catch (error) {
      setArticleContent('<p class="text-red-500">无法加载文档内容。</p>');
    } finally {
      setIsLoading(false);
    }
  };

  const handleAddComment = (e: React.FormEvent, parentId?: string) => {
    e.preventDefault();
    const name = parentId ? "匿名访客" : commentName;
    const text = parentId ? replyText : commentText;

    if (!text || !selectedProjectId || !activeProject) return;
    if (!parentId && !commentName) return;

    const newComment: Comment = {
      id: Date.now().toString(),
      projectId: selectedProjectId,
      projectDisplayName: activeProject.name,
      author: name,
      content: text,
      date: new Date().toLocaleDateString('zh-CN', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }),
      parentId: parentId
    };

    onUpdateComments([newComment, ...comments]);

    if (parentId) {
      setReplyToId(null);
      setReplyText('');
    } else {
      setCommentName('');
      setCommentText('');
    }
  };

  const handleDeleteComment = (id: string) => {
    if (window.confirm('确定要删除这条评论及其所有回复吗？')) {
      onUpdateComments(comments.filter(c => c.id !== id && c.parentId !== id));
    }
  };

  const renderCommentThread = (comment: Comment, allComments: Comment[]) => {
    const replies = allComments.filter(c => c.parentId === comment.id);

    return (
      <div key={comment.id} className="space-y-4">
        <div className="group p-6 bg-white border border-slate-100 rounded-3xl shadow-sm hover:shadow-md transition-all relative">
          <div className="flex justify-between items-start mb-2">
            <div className="flex items-center space-x-3">
              <div className="w-8 h-8 rounded-full bg-indigo-100 flex items-center justify-center text-xs font-bold text-indigo-600">
                {comment.author[0]?.toUpperCase()}
              </div>
              <span className="font-bold text-slate-900">{comment.author}</span>
            </div>
            <div className="flex items-center space-x-4">
              <span className="text-[10px] text-slate-400 font-medium">{comment.date}</span>
              <button 
                onClick={() => setReplyToId(replyToId === comment.id ? null : comment.id)}
                className="text-xs font-bold text-indigo-600 hover:underline"
              >
                回复
              </button>
              {isAdmin && (
                <button 
                  onClick={() => handleDeleteComment(comment.id)}
                  className="p-2 text-red-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-all opacity-0 group-hover:opacity-100"
                >
                  <ICONS.Trash className="w-4 h-4" />
                </button>
              )}
            </div>
          </div>
          <p className="text-sm text-slate-600 leading-relaxed pl-11">{comment.content}</p>

          {replyToId === comment.id && (
            <div className="mt-4 pl-11 animate-in slide-in-from-top-2 duration-200">
              <div className="flex gap-2">
                <input 
                  autoFocus
                  className="flex-1 p-2 bg-slate-50 border border-slate-200 rounded-xl text-xs outline-none focus:ring-1 focus:ring-indigo-500"
                  placeholder={`回复 ${comment.author}...`}
                  value={replyText}
                  onChange={e => setReplyText(e.target.value)}
                />
                <button 
                  onClick={(e) => handleAddComment(e, comment.id)}
                  className="px-4 py-2 bg-indigo-600 text-white rounded-xl text-xs font-bold"
                >
                  发送
                </button>
              </div>
            </div>
          )}
        </div>

        {replies.length > 0 && (
          <div className="ml-12 border-l-2 border-slate-100 pl-6 space-y-4">
            {replies.map(reply => (
              <div key={reply.id} className="group p-4 bg-slate-50/50 border border-slate-100 rounded-2xl relative">
                <div className="flex justify-between items-start mb-1">
                  <div className="flex items-center space-x-2">
                    <span className="font-bold text-xs text-slate-900">{reply.author}</span>
                    <span className="text-[10px] text-slate-400 font-medium">{reply.date}</span>
                  </div>
                  {isAdmin && (
                    <button 
                      onClick={() => handleDeleteComment(reply.id)}
                      className="text-red-400 opacity-0 group-hover:opacity-100 transition-all"
                    >
                      <ICONS.Trash className="w-3 h-3" />
                    </button>
                  )}
                </div>
                <p className="text-xs text-slate-600 leading-relaxed">{reply.content}</p>
              </div>
            ))}
          </div>
        )}
      </div>
    );
  };

  if (selectedProjectId && activeProject) {
    const projectComments = comments.filter(c => c.projectId === selectedProjectId);
    const rootComments = projectComments.filter(c => !c.parentId);

    return (
      <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 space-y-8 pb-20">
        <button 
          onClick={() => setSelectedProjectId(null)}
          className="flex items-center space-x-2 text-indigo-600 hover:text-indigo-700 font-bold transition-colors"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M15 19l-7-7 7-7" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round"/></svg>
          <span>返回项目列表</span>
        </button>

        <div className="bg-white rounded-[40px] border border-slate-200 overflow-hidden shadow-sm">
          <div className="h-64 overflow-hidden relative">
            <img src={activeProject.image} className="w-full h-full object-cover" alt="" />
            <div className="absolute inset-0 bg-gradient-to-t from-white via-white/20 to-transparent" />
          </div>

          <div className="p-8 md:p-12 -mt-20 relative">
            <div className="flex flex-wrap gap-2 mb-4">
              {activeProject.tech.map(t => (
                <span key={t} className="px-3 py-1 bg-indigo-100 text-indigo-700 text-[10px] font-bold uppercase tracking-widest rounded-full">{t}</span>
              ))}
            </div>
            <h1 className="text-4xl font-extrabold mb-8">{activeProject.name}</h1>

            {isLoading ? (
              <div className="flex justify-center py-20">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600"></div>
              </div>
            ) : (
              <div 
                className="prose max-w-none mb-16"
                dangerouslySetInnerHTML={{ __html: articleContent }}
              />
            )}

            <div className="border-t border-slate-100 pt-12">
              <h2 className="text-2xl font-bold mb-8">访客互动 ({projectComments.length})</h2>

              <form onSubmit={handleAddComment} className="bg-slate-50 p-6 rounded-3xl space-y-4 mb-10">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <input 
                    type="text" 
                    placeholder="您的昵称" 
                    value={commentName}
                    onChange={(e) => setCommentName(e.target.value)}
                    className="p-3 bg-white border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm"
                  />
                </div>
                <textarea 
                  placeholder="说点什么吧..." 
                  value={commentText}
                  onChange={(e) => setCommentText(e.target.value)}
                  className="w-full p-4 h-32 bg-white border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-indigo-500 text-sm resize-none"
                />
                <button type="submit" className="px-8 py-3 bg-indigo-600 text-white rounded-xl font-bold hover:bg-indigo-700 transition-all shadow-md">
                  发表评论
                </button>
              </form>

              <div className="space-y-8">
                {rootComments.length > 0 ? rootComments.map(c => renderCommentThread(c, projectComments)) : (
                  <div className="text-center py-10 bg-slate-50 rounded-3xl border border-dashed border-slate-200">
                    <p className="text-slate-400 text-sm">暂无评论，快来抢沙发吧！</p>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500">
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
        <div className="max-w-xl">
          <h1 className="text-3xl font-bold tracking-tight">项目作品</h1>
          <p className="text-slate-500 mt-2">涵盖从企业级平台到实验性的 UI/UX 研究。</p>
        </div>

        <div className="relative group min-w-[300px]">
          <div className="absolute inset-y-0 left-4 flex items-center pointer-events-none">
            <svg className="w-5 h-5 text-slate-400 group-focus-within:text-indigo-600 transition-colors" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" strokeWidth={2}/></svg>
          </div>
          <input 
            type="text" 
            placeholder="搜索项目、技术栈或描述..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-12 pr-4 py-3 bg-white border border-slate-200 rounded-2xl outline-none focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition-all shadow-sm"
          />
        </div>
      </div>

      <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-8">
        {filteredProjects.length > 0 ? filteredProjects.map((project) => (
          <div 
            key={project.id} 
            onClick={() => setSelectedProjectId(project.id)}
            className="group bg-white rounded-[32px] border border-slate-200 overflow-hidden shadow-sm hover:shadow-2xl transition-all duration-500 flex flex-col cursor-pointer hover:-translate-y-1"
          >
            <div className="relative overflow-hidden h-52">
              <img src={project.image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" alt={project.name} />
              <div className="absolute top-4 right-4 flex gap-2">
                {project.isFeatured && <span className="bg-indigo-600 text-white px-2 py-0.5 rounded text-[8px] font-bold uppercase tracking-tighter">精选</span>}
                {project.isLatest && <span className="bg-green-600 text-white px-2 py-0.5 rounded text-[8px] font-bold uppercase tracking-tighter">最新</span>}
              </div>
            </div>
            <div className="p-7 flex-1 flex flex-col">
              <h3 className="text-xl font-bold mb-2 group-hover:text-indigo-600 transition-colors">{project.name}</h3>
              <p className="text-slate-500 text-sm mb-4 line-clamp-2">{project.description}</p>

              <div className="flex flex-wrap gap-1.5 pt-4 border-t border-slate-50 mt-auto">
                {project.tech.map(tag => (
                  <span key={tag} className="px-2 py-1 bg-indigo-50 text-indigo-600 text-[9px] font-bold rounded-md uppercase tracking-tight">
                    {tag}
                  </span>
                ))}
              </div>
            </div>
          </div>
        )) : (
          <div className="col-span-full py-20 text-center bg-white rounded-[40px] border border-dashed border-slate-200">
            <p className="text-slate-400">没有找到匹配的项目，换个关键词试试？</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default Projects;

import { initializeApp } from "firebase/app";
import { 
  getFirestore, 
  collection, 
  addDoc, 
  onSnapshot, 
  query, 
  orderBy, 
  deleteDoc, 
  doc,
  Timestamp 
} from "firebase/firestore";
import { Comment } from "../types";

// Firebase 配置项，将通过环境变量注入
const firebaseConfig = {
  apiKey: process.env.FIREBASE_API_KEY || process.env.API_KEY,
  authDomain: process.env.FIREBASE_AUTH_DOMAIN,
  projectId: process.env.FIREBASE_PROJECT_ID,
  storageBucket: process.env.FIREBASE_STORAGE_BUCKET,
  messagingSenderId: process.env.FIREBASE_MESSAGING_SENDER_ID,
  appId: process.env.FIREBASE_APP_ID
};

let db: any = null;
try {
  // 仅在配置了 ProjectId 时初始化，防止未配置环境时崩溃
  if (firebaseConfig.projectId) {
    const app = initializeApp(firebaseConfig);
    db = getFirestore(app);
  }
} catch (e) {
  console.error("Firebase initialization failed:", e);
}

/**
 * 实时订阅所有评论
 */
export const subscribeComments = (callback: (comments: Comment[]) => void) => {
  if (!db) {
    console.warn("Firestore 未连接。评论将回退至本地存储。");
    return () => {};
  }

  const q = query(collection(db, "comments"), orderBy("createdAt", "desc"));
  return onSnapshot(q, (snapshot) => {
    const comments: Comment[] = [];
    snapshot.forEach((doc) => {
      const data = doc.data();
      comments.push({
        id: doc.id,
        projectId: data.projectId,
        projectDisplayName: data.projectDisplayName,
        author: data.author,
        content: data.content,
        date: data.date,
        parentId: data.parentId
      });
    });
    callback(comments);
  });
};

/**
 * 保存评论到 Firestore
 */
export const saveCommentToCloud = async (comment: Omit<Comment, 'id'>) => {
  if (!db) return null;
  const docRef = await addDoc(collection(db, "comments"), {
    ...comment,
    createdAt: Timestamp.now() // 用于排序
  });
  return docRef.id;
};

/**
 * 从 Firestore 删除评论
 */
export const removeCommentFromCloud = async (id: string) => {
  if (!db) return;
  await deleteDoc(doc(db, "comments", id));
};

export const isFirebaseActive = () => !!db;

import React, { useState, useEffect } from 'react';
import { Page, Project, Comment } from './types';
import { ICONS, INITIAL_PROJECTS } from './constants';
import Sidebar from './components/Sidebar';
import Home from './pages/Home';
import Projects from './pages/Projects';
import Tools from './pages/Tools';
import More from './pages/More';
import AdminDashboard from './pages/AdminDashboard';
import { subscribeComments, isFirebaseActive } from './services/firebase';

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState<Page>(Page.HOME);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
  const [isAdmin, setIsAdmin] = useState(() => localStorage.getItem('nova_is_admin') === 'true');
  const [showLoginModal, setShowLoginModal] = useState(false);
  const [loginPwd, setLoginPwd] = useState('');
  const [loginError, setLoginError] = useState('');

  // 项目列表依然保持在 localStorage/初始常量（通常这类数据是静态的）
  const [projects, setProjects] = useState<Project[]>(() => {
    const saved = localStorage.getItem('nova_projects');
    return saved ? JSON.parse(saved) : INITIAL_PROJECTS;
  });

  // 评论状态：如果 Firebase 激活则从云端同步，否则回退到 localStorage
  const [comments, setComments] = useState<Comment[]>([]);

  useEffect(() => {
    localStorage.setItem('nova_projects', JSON.stringify(projects));
  }, [projects]);

  useEffect(() => {
    // 处理评论持久化
    if (isFirebaseActive()) {
      // 订阅云端实时更新，无需手动 setItem
      const unsubscribe = subscribeComments((newComments) => {
        setComments(newComments);
      });
      return () => unsubscribe();
    } else {
      // 回退逻辑：从本地读取
      const saved = localStorage.getItem('nova_comments');
      if (saved) setComments(JSON.parse(saved));
    }
  }, []);

  // 当 Firebase 不可用时，同步状态到本地作为备份
  useEffect(() => {
    if (!isFirebaseActive()) {
      localStorage.setItem('nova_comments', JSON.stringify(comments));
    }
  }, [comments]);

  useEffect(() => {
    const handleResize = () => {
      const isMobile = window.innerWidth < 768;
      setIsSidebarOpen(!isMobile);
      if (isMobile) setIsSidebarCollapsed(false);
    };
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    // 校验混淆后的密码 'chen1234！'
    const encoded = btoa(unescape(encodeURIComponent(loginPwd)));
    if (encoded === 'Y2hlbjEyMzTvvMEx') {
      setIsAdmin(true);
      localStorage.setItem('nova_is_admin', 'true');
      setShowLoginModal(false);
      setLoginPwd('');
      setLoginError('');
    } else {
      setLoginError('身份校验失败，请检查管理通行证');
    }
  };

  const handleLogout = () => {
    setIsAdmin(false);
    localStorage.removeItem('nova_is_admin');
    if (currentPage === Page.ADMIN) setCurrentPage(Page.HOME);
  };

  const renderPage = () => {
    switch (currentPage) {
      case Page.HOME: return <Home projects={projects} onNavigate={setCurrentPage} />;
      case Page.PROJECTS: return (
        <Projects 
          isAdmin={isAdmin} 
          projects={projects} 
          comments={comments} 
          onUpdateComments={setComments} 
        />
      );
      case Page.TOOLS: return <Tools />;
      case Page.MORE: return <More />;
      case Page.ADMIN: return isAdmin ? (
        <AdminDashboard 
          projects={projects} 
          setProjects={setProjects} 
          onLogout={handleLogout}
        />
      ) : <Home projects={projects} onNavigate={setCurrentPage} />;
      default: return <Home projects={projects} onNavigate={setCurrentPage} />;
    }
  };

  // Add missing return JSX and export
  return (
    <div className="flex min-h-screen bg-slate-50">
      <Sidebar 
        activePage={currentPage} 
        onPageChange={setCurrentPage} 
        isOpen={isSidebarOpen}
        isCollapsed={isSidebarCollapsed}
        onToggleCollapse={() => setIsSidebarCollapsed(!isSidebarCollapsed)}
        onClose={() => setIsSidebarOpen(false)}
        isAdmin={isAdmin}
        onOpenLogin={() => setShowLoginModal(true)}
      />

      <main className={`flex-1 transition-all duration-300 ${isSidebarCollapsed ? 'md:ml-20' : 'md:ml-64'}`}>
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
          {renderPage()}
        </div>
      </main>

      {/* Login Modal */}
      {showLoginModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
          <div className="bg-white rounded-[32px] p-8 w-full max-w-md shadow-2xl animate-in zoom-in-95 duration-200">
            <div className="flex justify-between items-center mb-6">
