// Fix: Use standard modular import for initializeApp from firebase/app
import { initializeApp } from "firebase/app";
import { 
  getFirestore, 
  collection, 
  addDoc, 
  onSnapshot, 
  query, 
  orderBy, 
  deleteDoc, 
  doc,
  Timestamp 
} from "firebase/firestore";
import { Comment } from "../types";

// Firebase 配置项，将通过环境变量注入
const firebaseConfig = {
  apiKey: process.env.FIREBASE_API_KEY || process.env.API_KEY,
  authDomain: process.env.FIREBASE_AUTH_DOMAIN,
  projectId: process.env.FIREBASE_PROJECT_ID,
  storageBucket: process.env.FIREBASE_STORAGE_BUCKET,
  messagingSenderId: process.env.FIREBASE_MESSAGING_SENDER_ID,
  appId: process.env.FIREBASE_APP_ID
};

let db: any = null;
try {
  // 仅在配置了 ProjectId 时初始化，防止未配置环境时崩溃
  if (firebaseConfig.projectId) {
    const app = initializeApp(firebaseConfig);
    db = getFirestore(app);
  }
} catch (e) {
  console.error("Firebase initialization failed:", e);
}

/**
 * 实时订阅所有评论
 */
export const subscribeComments = (callback: (comments: Comment[]) => void) => {
  if (!db) {
    console.warn("Firestore 未连接。评论将回退至本地存储。");
    return () => {};
  }

  const q = query(collection(db, "comments"), orderBy("createdAt", "desc"));
  return onSnapshot(q, (snapshot) => {
    const comments: Comment[] = [];
    snapshot.forEach((doc) => {
      const data = doc.data();
      comments.push({
        id: doc.id,
        projectId: data.projectId,
        projectDisplayName: data.projectDisplayName,
        author: data.author,
        content: data.content,
        date: data.date,
        parentId: data.parentId
      });
    });
    callback(comments);
  });
};

/**
 * 保存评论到 Firestore
 */
export const saveCommentToCloud = async (comment: Omit<Comment, 'id'>) => {
  if (!db) return null;
  const docRef = await addDoc(collection(db, "comments"), {
    ...comment,
    createdAt: Timestamp.now() // 用于排序
  });
  return docRef.id;
};

/**
 * 从 Firestore 删除评论
 */
export const removeCommentFromCloud = async (id: string) => {
  if (!db) return;
  await deleteDoc(doc(db, "comments", id));
};

export const isFirebaseActive = () => !!db;

