            <div className="p-7 flex-1 flex flex-col">
              <h3 className="text-xl font-bold mb-2 group-hover:text-indigo-600 transition-colors">{project.name}</h3>
              <p className="text-slate-500 text-sm mb-4 line-clamp-2">{project.description}</p>

              <div className="flex flex-wrap gap-1.5 pt-4 border-t border-slate-50 mt-auto">
                {project.tech.map(tag => (
                  <span key={tag} className="px-2 py-1 bg-indigo-50 text-indigo-600 text-[9px] font-bold rounded-md uppercase tracking-tight">
                    {tag}
                  </span>
                ))}
              </div>
            </div>
          </div>
        )) : (
          <div className="col-span-full py-20 text-center bg-white rounded-[40px] border border-dashed border-slate-200">
            <p className="text-slate-400">未找到相关项目。</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default Projects;

import React from 'react';
import { Project } from '../types';
import { ICONS } from '../constants';

interface AdminDashboardProps {
  projects: Project[];
  setProjects: (projects: Project[]) => void;
  onLogout: () => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ projects, setProjects, onLogout }) => {
  const toggleFeatured = (id: string) => {
    setProjects(projects.map(p => p.id === id ? { ...p, isFeatured: !p.isFeatured } : p));
  };

  const toggleLatest = (id: string) => {
    setProjects(projects.map(p => p.id === id ? { ...p, isLatest: !p.isLatest } : p));
  };

  return (
    <div className="space-y-10 animate-in fade-in duration-500 pb-20">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">管理员控制台</h1>
